package com.aicharacter.v3;
/** Fast balance/proprioceptive reflexes. Corrections constrain mechanics before cognition. */
public final class NervousSystemEngine{private NervousSystemEngine(){}
 public static void advance(WorldState s,double dt,long now){if(s==null||dt<=0)return;if(s.nervous==null)s.nervous=new NervousState();NervousState n=s.nervous;PhysicsBodyState p=s.girlPhysics;BodyRigState r=s.bodyRig;if(p==null||r==null)return;double support=Math.max(.06,p.supportRight-p.supportLeft),edge=Math.max(0,Math.abs(p.centerOfMassX)-support*.28)/(support*.55),slip=Math.max(0,1-p.traction),footMismatch=0;if(Double.isFinite(r.leftFootGroundY)&&Double.isFinite(r.rightFootGroundY))footMismatch=Math.min(1,Math.abs(r.leftFootGroundY-r.rightFootGroundY)/WorldUnits.mToPx(.28));double landing=p.landingInstability;double footSlip=Math.max(r.leftFootSlip,r.rightFootSlip),slipAsym=Math.abs(r.leftFootSlip-r.rightFootSlip),physicalSlip=Math.max(p.slipSeverity,footSlip);double targetError=cl(edge*.62+slip*.18+physicalSlip*.62+footMismatch*.22+landing*.58+slipAsym*.38);n.proprioceptiveError=follow(n.proprioceptiveError,targetError,dt,.12);n.balanceAlarm=follow(n.balanceAlarm,cl((1-p.balance)*.75+n.proprioceptiveError*.55),dt,.08);n.protectiveReflex=follow(n.protectiveReflex,Math.max(n.balanceAlarm,s.bodyInstinct==null?0:s.bodyInstinct.guarding*.55),dt,.10);n.motorCorrection=follow(n.motorCorrection,cl(n.balanceAlarm*.82+n.proprioceptiveError*.48),dt,.07);double airborne=p.grounded?0:1,fallSpeed=Math.min(1,Math.abs(p.velocityY)/4.5);n.fallBrace=follow(n.fallBrace,airborne*fallSpeed,dt,.06);n.headProtection=follow(n.headProtection,Math.max(n.fallBrace,n.protectiveReflex*.55),dt,.05);n.armProtection=follow(n.armProtection,n.fallBrace*.82,dt,.07);if(p.grounded){p.landingInstability=Math.max(0,p.landingInstability-dt*(.32+n.motorCorrection*.48));double sign=p.centerOfMassX==0?0:Math.signum(p.centerOfMassX);p.centerOfMassX-=sign*n.motorCorrection*Math.min(.035,dt*.12);double widen=n.motorCorrection*.07;p.supportLeft-=widen;p.supportRight+=widen;}n.lastUpdatedAt=Math.max(n.lastUpdatedAt,now);}
 public static double locomotorConstraint(WorldState s){NervousState n=s==null?null:s.nervous;return n==null?1:Math.max(.38,1-n.balanceAlarm*.38-n.protectiveReflex*.16);}private static double follow(double v,double t,double dt,double tau){double k=1-Math.exp(-dt/Math.max(.02,tau));return cl(v+(t-v)*k);}private static double cl(double v){return Math.max(0,Math.min(1,v));}}
